import os,json,socket,fcntl,struct,pathlib,datetime,hashlib
r=pathlib.Path('/refactor');m=json.loads((r/'incoming/Kimi-PP4-crossalloc-r9154/resources.json').read_text());group=int(os.environ['PP4_GROUP_R9154']);g=m['target_groups'][group];local=int(os.environ['SLURM_PROCID']);offset=int(os.environ['GLOBAL_OFFSET_R2354']);node=offset+local;host=socket.gethostname();cpus=sorted(os.sched_getaffinity(0));assert offset==g['offset']and local in range(4)and host==g['nodes'][local]and m['target_nodes'][node]==host;assert os.environ['SLURM_JOB_ID']==g['parent'];assert int(os.environ['SLURM_CPUS_PER_TASK'])==64 and len(cpus)>=64;assert all(os.environ.get(k,'')==''for k in ['CUDA_VISIBLE_DEVICES','HIP_VISIBLE_DEVICES','ROCR_VISIBLE_DEVICES']);kfd=pathlib.Path('/sys/class/kfd/kfd/proc');pids=sorted(x.name for x in kfd.iterdir()if x.name.isdigit());assert not pids,pids
with socket.socket(socket.AF_INET,socket.SOCK_DGRAM)as s:raw=fcntl.ioctl(s.fileno(),0x8915,struct.pack('256s',b'ib0'))
ip=socket.inet_ntoa(raw[20:24]);assert ip.startswith('12.');print(json.dumps({'run':os.environ['GLOBAL_RUN_R2354'],'nonce_SHA256':hashlib.sha256(os.environ['KIMI_ENGINE_NONCE'].encode()).hexdigest(),'passed':True,'hostname':host,'group':group,'local_rank':local,'global_node':node,'global_offset':offset,'world_node_count':8,'PP_stage':node//2,'TP_node_rank':node%2,'world_GPU_ranks':list(range(8*node,8*node+8)),'TP_GPU_ranks':list(range(8*(node%2),8*(node%2)+8)),'actual_step':os.environ['SLURM_JOB_ID']+'.'+os.environ['SLURM_STEP_ID'],'actual_jobname':os.environ['SLURM_JOB_NAME'],'requested_CPUs':64,'affinity_count':len(cpus),'affinity':cpus,'ib0_IPv4':ip,'kfd_pids':pids,'GPU_API_initialized':False,'UTC':datetime.datetime.now(datetime.timezone.utc).isoformat()}))
